mobile.vertexShader:
uniform float uTime;
uniform float uAmbient;
uniform float uStart[16];
uniform float uCenterX[16];
uniform float uCenterY[16];
uniform float uStrength[16];
varying vec2 vGradient;
varying float vHeight;
void main(){
 vec2 p=position.xy;float raw=0.0;vec2 gradient=vec2(0.0);
 if(uAmbient>0.5){{vec2 direction=vec2(0.9578262852211513,0.2873478855663454);float k=6.613879270715354;float phase=k*(dot(direction,p)-0.1*uTime)+0.4;raw+=0.0016*sin(phase);gradient+=0.0016*k*cos(phase)*direction;}
{vec2 direction=vec2(-0.37139067635410367,0.9284766908852592);float k=9.973310011396169;float phase=k*(dot(direction,p)-0.08*uTime)+2.1;raw+=0.001*sin(phase);gradient+=0.001*k*cos(phase)*direction;}
{vec2 direction=vec2(0.6585046078685182,-0.7525766947068779);float k=16.98158191129618;float phase=k*(dot(direction,p)-0.06*uTime)+4.2;raw+=0.0006*sin(phase);gradient+=0.0006*k*cos(phase)*direction;}}
 for(int i=0;i<16;i++){
  float start=uStart[i];if(start<0.0)continue;
  float age=uTime-start;if(age<0.0||age>=8.0)continue;
  vec2 q=p-vec2(uCenterX[i],uCenterY[i]);
  float r=sqrt(dot(q,q)+0.00032399999999999996);
  float delta=r-0.42*age;
  float fade=clamp((8.0-age)/0.5,0.0,1.0);fade=fade*fade*(3.0-2.0*fade);
  float amplitude=0.014*clamp(uStrength[i],0.0,1.0)*(1.0-exp(-age/0.1))*exp(-0.75*age)*fade;
  float envelope=exp(-0.5*delta*delta/0.0324);
  float phase=44.87989505128275*delta;
  float c=cos(phase);raw+=amplitude*envelope*c;
  float radial=amplitude*envelope*(-delta/0.0324*c-44.87989505128275*sin(phase));
  gradient+=radial*q/r;
 }
 float capped=tanh(raw/0.035);
 vHeight=0.035*capped;
 vGradient=gradient*(1.0-capped*capped);
 gl_Position=projectionMatrix*modelViewMatrix*vec4(position.xy,vHeight,1.0);
}

mobile.fragmentShader:
uniform vec3 uBase;
uniform vec3 uReflectionLow;
uniform vec3 uReflectionHigh;
varying vec2 vGradient;
varying float vHeight;
void main(){
 vec3 normal=normalize(vec3(-vGradient,1.0));
 vec3 light=normalize(vec3(-0.6,0.75,1.0));
 vec3 view=vec3(0.0,0.0,1.0);
 vec3 reflection=reflect(-view,normal);
 vec3 environment=mix(uReflectionLow,uReflectionHigh,smoothstep(-0.45,0.45,reflection.y));
 float diffuse=0.74+0.26*max(dot(normal,light),0.0);
 float specular=0.34*pow(max(dot(normal,normalize(light+view)),0.0),64.0);
 vec3 color=mix(uBase*diffuse,environment,0.42)+specular*vec3(1.0,0.99,0.94);
 gl_FragColor=vec4(color,1.0);
 #include <tonemapping_fragment>
 #include <colorspace_fragment>
}
